  'admin.health.stopLoad': { en: 'Finish and delete test data', es: 'Terminar y borrar los datos de prueba' },
  'admin.health.prompts': { en: 'Prompts', es: 'Instrucciones' },
  'admin.health.exactlyWhatQuestionDesk': { en: 'Exactly what Question Desk asks Gemini, for each thing it does. Edit it to suit your audience; changes apply to the very next request. The rules underneath each prompt are always added and can\'t be edited — they are what keeps a question from being treated as an instruction, keeps topic labels in one language so questions group across languages, and keeps criticism unsoftened.', es: 'Exactamente lo que Question Desk le pide a Gemini para cada cosa que hace. Edítalo para que encaje con tu público; los cambios valen desde la siguiente petición. Las reglas que van debajo de cada instrucción se añaden siempre y no se pueden editar: son las que impiden que una pregunta se trate como una orden, las que mantienen los nombres de los temas en un solo idioma para que las preguntas se agrupen entre idiomas, y las que impiden suavizar las críticas.' },
  'admin.health.promptsave': { en: 'Save prompt', es: 'Guardar instrucción' },
  'admin.health.promptreset': { en: 'Reset to the built-in one', es: 'Restablecer la original' },
  'admin.health.alwaysAddedWhateverYou': { en: 'Always added, whatever you write', es: 'Se añade siempre, escribas lo que escribas' },
  'admin.health.gemini': { en: 'Gemini', es: 'Gemini' },
  'admin.health.howQuestionDeskAsks': { en: 'How Question Desk asks Gemini to group, merge and translate. Saved changes apply to the very next request — no redeploy. More thinking can group and translate messy or mixed-language questions better, but takes longer; less thinking answers faster.', es: 'Cómo le pide Question Desk a Gemini que agrupe, reúna y traduzca. Los cambios guardados valen desde la siguiente petición, sin volver a desplegar. Más razonamiento puede agrupar y traducir mejor las preguntas confusas o en varios idiomas, pero tarda más; menos razonamiento responde antes.' },
  'admin.health.gemkey.hint': { en: 'Paste a new key to replace it', es: 'Pega una clave nueva para sustituirla' },
