  'admin.health.mergeIntoOneQuestion': { en: '"Merge into one question": a facilitator is waiting.', es: '"Reunir en una pregunta": hay un facilitador esperando.' },
  'admin.health.showOnPhonesAnswer': { en: 'Show on phones, Answer now on one question, prepared questions.', es: 'Mostrar en los teléfonos, Responder ahora en una pregunta, preguntas preparadas.' },
  'admin.health.01LowerKeeps': { en: '0–1. Lower keeps topics and translations consistent and literal; 0–0.3 suits Question Desk.', es: '0–1. Más bajo mantiene los temas y las traducciones constantes y literales; de 0 a 0,3 le va bien a Question Desk.' },
  'admin.health.5100SmallerAnswers': { en: '5–100. Smaller answers sooner; larger groups a busy room in fewer requests.', es: '5–100. Más pequeño responde antes; más grande agrupa una sala concurrida en menos peticiones.' },
